SET local check_function_bodies = off;

CREATE TABLE "public"."plays" (
  "id"         bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "session_id" bigint,
  "video_id"   text   NOT NULL,
  "song_id"    bigint,
  "singer_id"  bigint,
  CONSTRAINT "plays_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."plays"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."queue_items" (
  "id"         bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "session_id" bigint NOT NULL,
  "video_id"   text   NOT NULL,
  "singer_id"  bigint,
  "position"   real   NOT NULL,
  CONSTRAINT "queue_items_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."queue_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."reactions" (
  "singer_id"  bigint                   NOT NULL,
  "song_id"    bigint                   NOT NULL,
  "value"      bigint                   NOT NULL,
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "reactions_pkey" PRIMARY KEY (singer_id, song_id)
);

ALTER TABLE "public"."reactions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."sessions" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"       text,
  "started_at" timestamp with time zone NOT NULL DEFAULT now(),
  "ended_at"   timestamp with time zone,
  CONSTRAINT "sessions_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."sessions"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."similar_songs" (
  "song_id"         bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "similar_song_id" bigint NOT NULL,
  "match"           real   NOT NULL,
  CONSTRAINT "similar_songs_pkey" PRIMARY KEY (song_id)
);

ALTER TABLE "public"."similar_songs"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."singers" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"       text                     NOT NULL,
  "avatar"     text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "singers_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."singers"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."songs" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "artist"            text                     NOT NULL DEFAULT ''::text,
  "title"             text                     NOT NULL DEFAULT ''::text,
  "match_key"         text                     NOT NULL DEFAULT ''::text,
  "lastfm_listeners"  bigint,
  "lastfm_playcount"  bigint,
  "tags"              text[],
  "lastfm_fetched_at" timestamp with time zone,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "songs_match_key_key" UNIQUE (match_key),
  CONSTRAINT "songs_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."songs"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."sources" (
  "id"                  bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "youtube_playlist_id" text                     NOT NULL,
  "name"                text                     NOT NULL,
  "channel_title"       text,
  "boost"               real                     NOT NULL DEFAULT '0'::real,
  "enabled"             boolean                  NOT NULL DEFAULT true,
  "last_synced_at"      timestamp with time zone,
  CONSTRAINT "sources_pkey" PRIMARY KEY (id),
  CONSTRAINT "sources_youtube_playlist_id_key" UNIQUE (youtube_playlist_id)
);

ALTER TABLE "public"."sources"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."video_sources" (
  "video_id"      text                     NOT NULL,
  "source_id"     bigint                   NOT NULL,
  "position"      bigint,
  "first_seen_at" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "video_sources_pkey" PRIMARY KEY (video_id, source_id)
);

ALTER TABLE "public"."video_sources"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."videos" (
  "youtube_id"    text   NOT NULL,
  "song_id"       bigint,
  "channel_id"    text   NOT NULL DEFAULT ''::text,
  "channel_title" text   NOT NULL DEFAULT ''::text,
  "raw_title"     text   NOT NULL DEFAULT ''::text,
  CONSTRAINT "videos_pkey" PRIMARY KEY (youtube_id)
);

ALTER TABLE "public"."videos"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "public"."added_via" AS ENUM (
  'playlist',
  'manual'
);

CREATE TYPE "public"."picked_by" AS ENUM (
  'queue',
  'autopilot'
);

ALTER TABLE "public"."plays"
  ADD COLUMN "picked_by" public.picked_by NOT NULL;

ALTER TABLE "public"."plays"
  ADD COLUMN "started_at" timestamp WITH time zone NOT NULL DEFAULT now();

ALTER TABLE "public"."plays"
  ADD COLUMN "ended_at" timestamp WITH time zone;

ALTER TABLE "public"."plays"
  ADD COLUMN "seconds_played" bigint;

CREATE TYPE "public"."play_outcome" AS ENUM (
  'completed',
  'skipped',
  'error'
);

ALTER TABLE "public"."plays"
  ADD COLUMN "outcome" public.play_outcome;

CREATE TYPE "public"."queue_status" AS ENUM (
  'queued',
  'playing',
  'done',
  'removed'
);

ALTER TABLE "public"."queue_items"
  ADD COLUMN "status" public.queue_status NOT NULL DEFAULT 'queued'::public.queue_status;

ALTER TABLE "public"."queue_items"
  ADD COLUMN "added_at" timestamp WITH time zone NOT NULL DEFAULT now();

CREATE TYPE "public"."video_status" AS ENUM (
  'ok',
  'not_embeddable',
  'region_blocked',
  'age_restricted',
  'unavailable'
);

CREATE TYPE "public"."video_version" AS ENUM (
  'standard',
  'lower_key',
  'higher_key',
  'duet',
  'other'
);

ALTER TABLE "public"."videos"
  ADD COLUMN "version" public.video_version NOT NULL DEFAULT 'standard'::public.video_version;

ALTER TABLE "public"."videos"
  ADD COLUMN "duration_sec" bigint;

ALTER TABLE "public"."videos"
  ADD COLUMN "view_count" bigint;

ALTER TABLE "public"."videos"
  ADD COLUMN "published_at" timestamp WITH time zone;

ALTER TABLE "public"."videos"
  ADD COLUMN "thumbnail_url" text;

ALTER TABLE "public"."videos"
  ADD COLUMN "status" public.video_status NOT NULL DEFAULT 'ok'::public.video_status;

ALTER TABLE "public"."videos"
  ADD COLUMN "last_player_error" bigint;

ALTER TABLE "public"."videos"
  ADD COLUMN "needs_review" boolean NOT NULL DEFAULT false;

ALTER TABLE "public"."videos"
  ADD COLUMN "added_via" public.added_via NOT NULL;

ALTER TABLE "public"."videos"
  ADD COLUMN "added_by" bigint;

ALTER TABLE "public"."videos"
  ADD COLUMN "stats_fetched_at" timestamp WITH time zone;

ALTER TABLE "public"."videos"
  ADD COLUMN "created_at" timestamp WITH time zone NOT NULL DEFAULT now();

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
  RETURNS event_trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'pg_catalog'
  AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

